// SEIS cockpit data-source adapter.
//
// One seam that decides where cockpit data comes from. Today it resolves the
// static bundle generated by scripts/create-cockpit-status.mjs
// (window.SEIS_COCKPIT_STATUS). At backend provisioning, a live provider can
// register the same-shaped data and flip the mode to "live" — the renderer in
// cockpit.js does not change, because both paths return one status object with
// the entity shapes defined in apps/fullstack/state-model.json.
//
// Live wiring (deferred, see docs/decisions/backend-state-decision-record.md):
//   1. A Convex client calls the generated reads in apps/fullstack/convex/queries.ts
//      (listGovernanceGates, listPluginLanes, ...).
//   2. It assembles the same status shape and calls
//      window.SEIS_COCKPIT_SOURCE.provideLive(status).
//   3. cockpit.js re-renders from the resolved source.
(function () {
  "use strict";

  var live = null;

  window.SEIS_COCKPIT_SOURCE = {
    // "static" until a live provider registers data.
    get mode() {
      return live ? "live" : "static";
    },

    // Returns the current status object, or null if no source is available yet.
    resolve: function () {
      return live || window.SEIS_COCKPIT_STATUS || null;
    },

    // Future live provider hook: supply same-shaped data and (if present) ask
    // the renderer to refresh. Kept side-effect-light so it is safe to call
    // before cockpit.js has registered a refresh handler.
    provideLive: function (status) {
      live = status;
      if (typeof window.SEIS_COCKPIT_REFRESH === "function") {
        window.SEIS_COCKPIT_REFRESH();
      }
    },
  };
})();
